  justify-content: center;
  gap: 14px;
  color: var(--text-muted);
}

.image-placeholder-icon {
  width: 64px;
  height: 64px;
  background: var(--surface-2);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
}

.image-placeholder-icon svg {
  opacity: 0.4;
}

.image-placeholder-label {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-secondary);
}

.image-placeholder-sub {
  font-size: 13px;
  color: var(--text-muted);
}

/* ── Preview nav arrows ─────────────────────────────── */

.preview-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 14px 24px;
  border-top: 1px solid var(--border);
  gap: 8px;
}

.thumb-nav {
  display: flex;
  align-items: center;
  gap: 8px;
}

.thumb {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  cursor: pointer;
  border: 2px solid transparent;
  overflow: hidden;
  transition: border-color var(--transition);
