}

.meta-item-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 3px;
}

.meta-item-value {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
}

.rating-stars {
  display: flex;
  gap: 3px;
  margin-top: 2px;
}

.star {
