  display: block;
  max-width: 580px;
  width: 100%;
  height: auto;
  object-fit: cover;
}

.image-placeholder {
  width: 580px;
  max-width: 100%;
  aspect-ratio: 4/3;
  background: var(--surface);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  color: var(--text-muted);
}

.image-placeholder-icon {
  width: 64px;
  height: 64px;
  background: var(--surface-2);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
