}

.image-placeholder-icon svg {
  opacity: 0.4;
}

.image-placeholder-label {
  font-size: 15px;
  font-weight: 600;
  color: var(--text-secondary);
}

.image-placeholder-sub {
  font-size: 13px;
  color: var(--text-muted);
}

