.preview-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 14px 24px;
  border-top: 1px solid var(--border);
  gap: 8px;
}

.thumb-nav {
  display: flex;
  align-items: center;
  gap: 8px;
}

.thumb {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--surface-2);
  cursor: pointer;
  border: 2px solid transparent;
  overflow: hidden;
  transition: border-color var(--transition);
  flex-shrink: 0;
}

.thumb.active {
  border-color: var(--accent);
}

.thumb-dot {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.thumb-dot::after {
  content: '';
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
}

/* ── Details panel ──────────────────────────────────── */

.details-panel {
  border-left: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}

.panel-header {
  padding: 20px 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.panel-title {
  font-size: 13px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--text-muted);
}

.panel-section {
  padding: 20px;
  border-bottom: 1px solid var(--border);
}

.panel-section:last-child {
  border-bottom: none;
}

.image-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 6px;
}

.image-meta-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: var(--surface-2);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 500;
  padding: 3px 9px;
  border-radius: 99px;
  margin-right: 6px;
  margin-bottom: 6px;
}

.meta-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.meta-item-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 3px;
}

.meta-item-value {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
}

.rating-stars {
  display: flex;
  gap: 3px;
  margin-top: 2px;
}

.star {
  color: var(--text-muted);
  font-size: 15px;
}

.star.filled {
  color: #f5a623;
}

.tags-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}

.tag {
  background: rgba(124, 111, 205, 0.12);
  color: var(--accent-hover);
  font-size: 12px;
  font-weight: 500;
  padding: 4px 10px;
  border-radius: 99px;
  border: 1px solid rgba(124, 111, 205, 0.2);
}

.panel-actions {
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.panel-actions .btn {
  width: 100%;
  justify-content: center;
}

