  transition: transform 220ms cubic-bezier(0.34, 1.2, 0.64, 1);
}

.modal-overlay.is-open .modal {
  transform: scale(1) translateY(0);
}

.modal-body {
  padding: 32px 28px 24px;
  text-align: center;
}

.modal-icon {
  width: 60px;
  height: 60px;
  background: var(--danger-subtle);
